// Aggregate last week's metrics (from the HTTP Request node) into pdfmill "report" data.
// The HTTP Request node puts the parsed JSON response on the item; if its "Full Response"
// option is enabled the body lands under `.body`, so accept either shape.
const res = $json.body ?? $json;

// --- Reporting period: the last 7 completed days (yesterday, back 6 days) ---
const iso = (d) => d.toISOString().slice(0, 10);
const now = new Date();
const periodEnd = new Date(now.getTime() - 24 * 60 * 60 * 1000);            // yesterday = last full day
const periodStart = new Date(periodEnd.getTime() - 6 * 24 * 60 * 60 * 1000); // 7-day trailing window
const short = (d) => `${d.getUTCMonth() + 1}/${d.getUTCDate()}`;
const humanRange = `${short(periodStart)}–${short(periodEnd)}`;

// --- Read this week + last week from the API response, with safe demo fallbacks ---
// (the fallbacks let the report render before you have wired up the real endpoint)
const cur = res.current ?? res.thisWeek ?? res;
const prev = res.previous ?? res.lastWeek ?? {};
const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);
const group = (n) => String(Math.round(num(n))).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const money = (n) => `$${group(n)}`;

const m = {
  signups: num(cur.signups, 1240),
  activeUsers: num(cur.activeUsers, 8630),
  revenue: num(cur.revenue, 18420),
  churnedUsers: num(cur.churnedUsers, 96),
};
const p = {
  signups: num(prev.signups, 1090),
  activeUsers: num(prev.activeUsers, 8210),
  revenue: num(prev.revenue, 16750),
  churnedUsers: num(prev.churnedUsers, 78),
};

// --- Derived helpers: percentage change (real minus sign) + good/bad direction ---
const pct = (c, b) => {
  if (!b) return '+0%';
  const change = ((c - b) / b) * 100;
  const sign = change > 0 ? '+' : (change < 0 ? '−' : '');
  return `${sign}${Math.abs(change).toFixed(1)}%`;
};
// higherIsBetter: revenue/signups/actives are "up" when they grow; churn is "up" when it shrinks
const dir = (c, b, higherIsBetter = true) => {
  const grew = c > b;
  return (higherIsBetter ? grew : !grew) ? 'up' : 'down';
};

const churnRate = m.activeUsers ? (m.churnedUsers / m.activeUsers) * 100 : 0;
const prevChurnRate = p.activeUsers ? (p.churnedUsers / p.activeUsers) * 100 : 0;
const arpu = m.activeUsers ? m.revenue / m.activeUsers : 0;

// --- KPIs: the churn KPI is a regression, so down:true renders its delta red ---
const kpis = [
  { label: 'New signups', value: group(m.signups), delta: pct(m.signups, p.signups), down: m.signups < p.signups },
  { label: 'Active users', value: group(m.activeUsers), delta: pct(m.activeUsers, p.activeUsers), down: m.activeUsers < p.activeUsers },
  { label: 'Weekly revenue', value: money(m.revenue), delta: pct(m.revenue, p.revenue), down: m.revenue < p.revenue },
  { label: 'Churned users', value: group(m.churnedUsers), delta: pct(m.churnedUsers, p.churnedUsers), down: m.churnedUsers > p.churnedUsers },
];

// --- Narrative summary + sections, all computed from the numbers above ---
const summary =
  `In the last 7 days the product added ${group(m.signups)} new signups (${pct(m.signups, p.signups)} vs the prior week) ` +
  `and reached ${group(m.activeUsers)} weekly active users. Revenue was ${money(m.revenue)} (${pct(m.revenue, p.revenue)}). ` +
  `${m.churnedUsers} users churned (${churnRate.toFixed(1)}% of actives), ` +
  `${m.churnedUsers > p.churnedUsers ? 'up from' : 'down from'} ${p.churnedUsers} the week before.`;

const sections = [
  {
    heading: 'Growth',
    body:
      `New signups ${m.signups >= p.signups ? 'rose' : 'fell'} to ${group(m.signups)} (${pct(m.signups, p.signups)}). ` +
      `Weekly active users are at ${group(m.activeUsers)} (${pct(m.activeUsers, p.activeUsers)} vs last week).`,
  },
  {
    heading: 'Revenue',
    body:
      `Revenue for the window was ${money(m.revenue)}, a ${pct(m.revenue, p.revenue)} move against ${money(p.revenue)} the week before. ` +
      `Average revenue per active user was $${arpu.toFixed(2)}.`,
  },
  {
    heading: 'Retention & churn',
    body:
      `${m.churnedUsers} users churned (${churnRate.toFixed(1)}% of the active base) versus ${p.churnedUsers} (${prevChurnRate.toFixed(1)}%) a week earlier. ` +
      `${m.churnedUsers > p.churnedUsers ? 'The uptick is the one metric to watch next week.' : 'Churn is trending the right way.'}`,
  },
];

// --- Comparison table: this week vs last week, each row tagged up/down ---
const table = {
  caption: `This week vs previous week (${humanRange})`,
  rows: [
    { label: 'New signups', current: group(m.signups), previous: group(p.signups), change: pct(m.signups, p.signups), direction: dir(m.signups, p.signups, true) },
    { label: 'Active users', current: group(m.activeUsers), previous: group(p.activeUsers), change: pct(m.activeUsers, p.activeUsers), direction: dir(m.activeUsers, p.activeUsers, true) },
    { label: 'Weekly revenue', current: money(m.revenue), previous: money(p.revenue), change: pct(m.revenue, p.revenue), direction: dir(m.revenue, p.revenue, true) },
    { label: 'Churn rate', current: `${churnRate.toFixed(1)}%`, previous: `${prevChurnRate.toFixed(1)}%`, change: pct(m.churnedUsers, p.churnedUsers), direction: dir(m.churnedUsers, p.churnedUsers, false) },
  ],
};

// --- Emit the pdfmill "report" data shape (see packages/templates/src/report/vars.ts) ---
return [{
  json: {
    kicker: 'Weekly metrics report',
    title: 'Weekly Performance Report',
    subtitle: `Signups, engagement, revenue and churn — ${humanRange}`,
    periodStart: iso(periodStart),
    periodEnd: iso(periodEnd),
    generatedAt: iso(now),
    author: 'Automated by n8n + pdfmill',
    summary,
    kpis,
    sections,
    table,
  },
}];
